mapper.select:
select crn.id, crn.club_id, crn.title, crn.type, crn.status, crn.number, crn.already, crn.time_type, crn.start_time, crn.end_time, crn.create_time, crn.sort, u.userName as clubName from club_recruitment_news crn left join user u on crn.club_id = u.id
and crn.title like concat('%', #{title}, '%')
and crn.type = #{type}
and crn.status = #{status}
and crn.time_type = #{timeType}
and crn.create_time >= #{createTimeStart}
and crn.create_time <= #{createTimeEnd}
and u.userName like concat('%', #{clubName}, '%')
order by sort desc , create_time desc
